var t=`0252-kleftiko-cypriot-style`;var n=`world-0252`;var o=`CY`;var a=`western-asia`;var r=4;var s=307;var l={en:`Kleftiko Cypriot Style`,ua:`Клефтіко по-кіпрськи`};var d={en:`A traditional Cyprus dish made with lamb shoulder, lemon juice, garlic, potato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Кіпр. Основні інгредієнти: лопатка ягняти, лимонний сік, часник, картопля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 150 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 150 хвилин.`,t:[`marinating`],m:150,i:[[`lamb-shoulder`,1100,`g`],[`extra-virgin-olive-oil`,80,`ml`],[`lemon-juice`,60,`ml`],[`garlic`,6,`clove`],[`dried-oregano`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Roast in a preheated 190°C oven for about 155 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 155 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:155,i:[[`potato`,650,`g`],[`yellow-onion`,200,`g`],[`water`,300,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[]}];var u={slug:t,id:n,country:`CY`,region:a,servings:4,minutes:307,title:l,text:d,steps:g};export{o as country,u as default,n as id,s as minutes,a as region,r as servings,t as slug,g as steps,d as text,l as title};